#!/usr/bin/env python3
"""Configure this decompilation project (generated by romwright new-project).

    python3 configure.py                  # fetch tools, extract the ROM, dsd init + merge, write build.ninja
    python3 configure.py swap NAME        # turn one ARM9/overlay function into a C unit
    python3 configure.py --arm7-bios F    # an encrypted dump needs the ARM7 BIOS (never stored here)

The build (`ninja`) is dsd's: `dsd delink` cuts the ARM9 program and its overlays into
relocatable objects, `dsd lcf` writes the linker script and object list, Metrowerks'
mwldarm links them, `dsd rom config` turns the linked ELF into a ds-rom configuration,
`dsd rom build` writes the ROM, and tools/romfix.py restores the two header fields
ds-rom cannot recompute (the secure area CRC of the retail header and the header CRC).
"""
import argparse
import glob
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "tools"))
import download_tool  # noqa: E402

PROJECT = json.loads((ROOT / "config" / "project.json").read_text())
NAME = PROJECT["image"]["file"]
BUILD = ROOT / "build"
DSD_CONFIG = ROOT / "config" / "dsd"
CONFIG_YAML = DSD_CONFIG / "arm9" / "config.yaml"
LOCAL_PROFILE = ROOT / "config" / "toolchain.local.json"
SWAPS = ROOT / "config" / "swaps.json"


# --------------------------------------------------------------------------
# Tools
# --------------------------------------------------------------------------

def load_profile(path):
    profile = json.loads(Path(path).read_text())
    for key, entry in (profile.get("tools") or {}).items():
        digest = (entry.get("digest") or "").lower()
        if digest and len(digest) == 64:
            actual = download_tool.sha256_file(entry["path"])
            if actual != digest:
                raise SystemExit(f"{path}: tool `{key}` ({entry['path']}) sha256 {actual} != profile digest {digest}")
    return profile


def resolve_tools(args):
    manifest = download_tool.load_manifest(args.manifest or ROOT / "config" / "toolchain.json")
    spec = PROJECT["tools"]
    profile_path = args.toolchain or (LOCAL_PROFILE if LOCAL_PROFILE.exists() else None)
    profile = load_profile(profile_path) if profile_path else {}
    given = {key: entry["path"] for key, entry in (profile.get("tools") or {}).items()}
    paths = {}

    def where(tool_id):
        if args.no_tools:
            return BUILD / "tools" / tool_id
        return download_tool.install(manifest[tool_id], BUILD / "tools", BUILD / "tools" / ".cache")

    paths["dsd"] = given.get("dsd") or str(where(spec["dsd"]) / "dsd")
    paths["wibo"] = given.get("wibo") or str(where("wibo") / "wibo")
    root = where(spec["compiler"]) / "mwccarm"
    if "compiler" in given:
        root = Path(given["compiler"]).parent.parent
    paths["mwccarm_root"] = str(root)
    version = root / PROJECT["compiler"]["mw_version"]
    # The archive carries one license.dat; the executables look for it beside themselves.
    license_file = root / "license.dat"
    if license_file.exists() and version.exists() and not (version / "license.dat").exists():
        shutil.copyfile(license_file, version / "license.dat")
    paths["mwldarm"] = given.get("linker") or str(version / "mwldarm.exe")
    if "objdiff-cli" in given:
        paths["objdiff-cli"] = given["objdiff-cli"]
    elif spec.get("report") and not args.no_tools:
        try:
            paths["objdiff-cli"] = str(where(spec["report"]) / "objdiff-cli")
        except SystemExit as error:
            print(f"warning: objdiff-cli unavailable ({error}); `ninja progress` is disabled", file=sys.stderr)
    BUILD.mkdir(exist_ok=True)
    (BUILD / "tools.json").write_text(json.dumps(paths, indent=2) + "\n")
    return paths


def run(argv, **kwargs):
    result = subprocess.run([str(a) for a in argv], cwd=ROOT, capture_output=True, text=True, **kwargs)
    if result.returncode != 0:
        sys.stderr.write(result.stdout + result.stderr)
        raise SystemExit(f"command failed ({result.returncode}): {' '.join(str(a) for a in argv)}")
    return result


# --------------------------------------------------------------------------
# extract / init / merge
# --------------------------------------------------------------------------

def extract(paths, args):
    target = ROOT / "extract"
    if (target / "config.yaml").exists():
        return
    rom = ROOT / PROJECT["image"]["orig"]
    if not rom.exists():
        raise SystemExit(f"{rom} is missing: put your retail ROM there")
    argv = [paths["dsd"], "rom", "extract", "--rom", rom, "--output-path", target]
    bios = args.arm7_bios or os.environ.get("ROMWRIGHT_ARM7_BIOS")
    if bios:
        argv += ["--arm7-bios", bios]
    print("dsd rom extract", flush=True)
    run(argv)


def init(paths, add_functions=True):
    if CONFIG_YAML.exists():
        return
    print("dsd init", flush=True)
    init_argv = [paths["dsd"], "init", "--rom-config", ROOT / "extract" / "config.yaml", "--output-path", DSD_CONFIG, "--build-path", BUILD / "dsd"]
    attempt = subprocess.run([str(a) for a in init_argv], cwd=ROOT, capture_output=True, text=True)
    if attempt.returncode != 0:
        # dsd stops on a local call that leads to no function it found; its own switch makes a symbol for the target.
        print("dsd init stopped (" + (attempt.stderr.strip().splitlines() or ["?"])[-1][:200] + "); retrying with --allow-unknown-function-calls", flush=True)
        shutil.rmtree(DSD_CONFIG, ignore_errors=True)
        run([*init_argv, "--allow-unknown-function-calls"])
    print("merge romwright symbols", flush=True)
    result = run([sys.executable, ROOT / "tools" / "merge_symbols.py", *([] if add_functions else ["--no-add"])])
    (BUILD / "merge_report.json").write_text(result.stdout)
    print(result.stdout.strip())
    validate(paths, json.loads(result.stdout))


def validate(paths, report):
    """`dsd delink` is the consumer that analyses every function: one romwright added that dsd cannot
    analyse (`InvalidStart`) is taken out again, and a config dsd still refuses is replaced by dsd's own."""
    added = set(report.get("added", []))
    removed = []
    for _ in range(200):
        check = subprocess.run([paths["dsd"], "delink", "--config-path", str(CONFIG_YAML)], cwd=ROOT, capture_output=True, text=True)
        if check.returncode == 0:
            break
        match = re.search(r"function (\S+) could not be analyzed", check.stdout + check.stderr)
        if not match or match.group(1) not in added:
            sys.stderr.write(check.stderr[-600:])
            print("warning: dsd rejects the merged symbols; keeping dsd's own", file=sys.stderr)
            for original in glob.glob(str(DSD_CONFIG / "**" / "*.dsd"), recursive=True):
                shutil.copyfile(original, original[: -len(".dsd")])
            return
        name = match.group(1)
        for path in glob.glob(str(DSD_CONFIG / "**" / "symbols.txt"), recursive=True):
            lines = Path(path).read_text().splitlines(keepends=True)
            kept = [l for l in lines if not l.startswith(name + " ")]
            if len(kept) != len(lines):
                Path(path).write_text("".join(kept))
        removed.append(name)
        added.discard(name)
    if removed:
        print(f"removed {len(removed)} romwright function(s) dsd cannot analyse: {', '.join(removed)}")
        report["added_functions"] -= len(removed)
        report["added"] = sorted(added)
        report["rejected_by_dsd"] = removed
        (BUILD / "merge_report.json").write_text(json.dumps(report) + "\n")


def write_names_header():
    """include/romwright_names.h: `#define <romwright name> <dsd name>` for the ARM9 program and its
    autoloads, so C written against romwright's names (`FUN_02010b18`, `DAT_0205ac20`) links against
    the symbols dsd's config calls them (`func_02010b18`, `data_0205ac20`). Overlays share addresses
    and names, so they are left out."""
    dsd_names = {}
    for module, directory in symbol_files().items():
        if module.startswith("ov"):
            continue
        for line in (directory / "symbols.txt").read_text().splitlines():
            row = re.match(r"^(\S+) kind:\w+(?:\(.*\))? addr:0x([0-9a-f]+)", line)
            if row:
                dsd_names.setdefault(int(row.group(2), 16), row.group(1))
    taken = set(dsd_names.values())
    lines = ["/* Generated by configure.py: romwright's names for dsd's symbols (ARM9 and autoloads). */\n"]
    for line in (ROOT / "config" / "romwright" / "main.symbols.txt").read_text().splitlines():
        row = re.match(r"^(\S+) kind:\w+(?:\(.*\))? addr:0x([0-9a-f]+)", line)
        if not row:
            continue
        name, address = row.group(1), int(row.group(2), 16)
        target = dsd_names.get(address)
        if target and target != name and name not in taken and re.fullmatch(r"[A-Za-z_]\w*", name):
            lines.append(f"#define {name} {target}\n")
    (ROOT / "include" / "romwright_names.h").write_text("".join(lines))


# --------------------------------------------------------------------------
# build.ninja
# --------------------------------------------------------------------------

def esc(path):
    return str(path).replace("$", "$$").replace(" ", "$ ").replace(":", "$:")


def quote(argv):
    return " ".join(shlex.quote(str(a)).replace("$", "$$") for a in argv)


def swaps():
    return json.loads(SWAPS.read_text()) if SWAPS.exists() else []


def write_build(paths):
    dsd_files = sorted(str(p.relative_to(ROOT)) for p in DSD_CONFIG.rglob("*") if p.is_file() and p.suffix in (".txt", ".yaml"))
    name = NAME
    dsd = quote([paths["dsd"]])
    c_objects = [f"build/dsd/{s['object']}" for s in swaps()]
    scratch = BUILD / "tmp"
    scratch.mkdir(parents=True, exist_ok=True)
    with open(ROOT / "build.ninja", "w") as out:
        w = out.write
        w("ninja_required_version = 1.7\n")
        w(f"python = {shlex.quote(sys.executable)}\n\n")
        w(f"rule delink\n  command = {dsd} delink --config-path {CONFIG_YAML.relative_to(ROOT)} && touch $out\n  description = dsd delink\n\n")
        w(f"rule lcf\n  command = {dsd} lcf --config-path {CONFIG_YAML.relative_to(ROOT)} && touch $out\n  description = dsd lcf\n\n")
        w("rule cc\n  command = $python tools/cc.py $out $in\n  description = cc $in\n\n")
        link = quote([paths["wibo"], paths["mwldarm"], "-proc", "arm946e", "-nostdlib", "-interworking", "-nodead", "-m", "Entry", "-map", "closure,unused", "-msgstyle", "gcc"])
        w(f"rule link\n  command = {link} @build/dsd/objects.txt build/dsd/arm9.lcf -o $out\n  description = mwldarm\n\n")
        w(f"rule romconfig\n  command = {dsd} rom config --elf $in --config {CONFIG_YAML.relative_to(ROOT)}\n  description = dsd rom config\n\n")
        w(f"rule rom\n  command = {dsd} rom build --config $in --rom $out\n  description = dsd rom build\n\n")
        w("rule fix\n  command = $python tools/romfix.py $in $out\n  description = header CRCs\n\n")
        w("rule verify\n  command = $python tools/verify.py $in config/checksum.sha1 $out\n  description = verify $in\n\n")
        w(f"rule report\n  command = {quote([paths.get('objdiff-cli', 'objdiff-cli')])} report generate -o $out\n  description = report\n\n")
        w(f"build build/dsd/.delinked: delink | {' '.join(esc(f) for f in dsd_files)}\n\n")
        w("build build/dsd/arm9.lcf build/dsd/objects.txt: lcf | build/dsd/.delinked\n\n")
        for swap in swaps():
            w(f"build build/dsd/{swap['object']}: cc {esc(swap['source'])} | include/romwright_types.h include/romwright_names.h config/project.json\n\n")
        w(f"build build/dsd/arm9.o: link build/dsd/arm9.lcf build/dsd/objects.txt | {' '.join(esc(o) for o in c_objects)}\n\n")
        w("build build/dsd/build/rom_config.yaml: romconfig build/dsd/arm9.o\n\n")
        w(f"build build/{name}.raw: rom build/dsd/build/rom_config.yaml\n\n")
        w(f"build build/{name}: fix build/{name}.raw | tools/romfix.py config/header.json\n\n")
        w(f"build build/{name}.ok: verify build/{name} | config/checksum.sha1\n\n")
        w(f"build all: phony build/{name}.ok\ndefault all\n")


# --------------------------------------------------------------------------
# swap
# --------------------------------------------------------------------------

def symbol_files():
    found = {"main": DSD_CONFIG / "arm9"}
    for kind in ("itcm", "dtcm"):
        found[kind] = DSD_CONFIG / "arm9" / kind
    for path in sorted((DSD_CONFIG / "arm9" / "overlays").glob("ov*")):
        found[path.name] = path
    return {module: directory for module, directory in found.items() if (directory / "symbols.txt").exists()}


ROW = re.compile(r"^(?P<name>\S+) kind:function\((?P<mode>arm|thumb),size=0x(?P<size>[0-9a-f]+).*\) addr:0x(?P<addr>[0-9a-f]+)")


def find_function(target, module):
    matches = []
    for name, directory in symbol_files().items():
        if module and name != module:
            continue
        for line in (directory / "symbols.txt").read_text().splitlines():
            row = ROW.match(line)
            if not row:
                continue
            if re.fullmatch(r"0x[0-9a-fA-F]+", target):
                hit = int(row["addr"], 16) == int(target, 16)
            else:
                hit = row["name"] == target
            if hit:
                matches.append((name, directory, row["name"], int(row["addr"], 16), int(row["size"], 16), row["mode"]))
    if not matches:
        raise SystemExit(f"`{target}` is not a function of the dsd config (config/dsd/arm9/**/symbols.txt)")
    if len(matches) > 1:
        raise SystemExit("`%s` is ambiguous (overlays share addresses); pass --module: %s" % (target, ", ".join(m[0] for m in matches)))
    return matches[0]


def swap(args):
    module, directory, name, address, size, _mode = find_function(args.function, args.module)
    delinks = directory / "delinks.txt"
    text = delinks.read_text()
    unit = f"src/{module}/{name}.c"
    if f"\n{unit}:" in "\n" + text:
        raise SystemExit(f"{name} is already a C unit")
    # A function is inside the module's `.text` section; the delink file is that range of it.
    text = text.rstrip("\n") + f"\n\n{unit}:\n    complete\n    .text start:{address:#010x} end:{address + size:#010x}\n"
    delinks.write_text(text)
    destination = ROOT / unit
    destination.parent.mkdir(parents=True, exist_ok=True)
    if args.src:
        shutil.copyfile(args.src, destination)
    elif not destination.exists():
        reference = ROOT / "decompiled" / f"{name}.c"
        body = reference.read_text() if reference.exists() else "/* write the C for this function; it must compile to exactly the retail bytes */\n"
        destination.write_text(body if body.startswith("#include") else '#include "romwright_types.h"\n\n' + body)
    rows = swaps()
    rows.append({"name": name, "module": module, "source": unit, "object": f"src/{module}/{name}.o", "start": address, "end": address + size})
    SWAPS.write_text(json.dumps(rows, indent=2) + "\n")
    print(f"{name}: dsd delink unit {unit} ({address:#010x}..{address + size:#010x}); C in {unit}")


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--toolchain", help="toolchain profile JSON (replaces manifest tools one by one)")
    parser.add_argument("--manifest", help="tool manifest (default config/toolchain.json)")
    parser.add_argument("--no-tools", action="store_true", help="do not download; use what is already in build/tools")
    parser.add_argument("--arm7-bios", help="ARM7 BIOS file, needed to decrypt an encrypted dump")
    parser.add_argument("--no-add-functions", dest="add_functions", action="store_false", help="only rename: do not add the functions romwright found and dsd did not")
    sub = parser.add_subparsers(dest="command")
    swap_parser = sub.add_parser("swap", help="turn one function into a C unit")
    swap_parser.add_argument("function", help="function name or 0xADDRESS")
    swap_parser.add_argument("--module", help="main, itcm, dtcm or ovNNN (overlays share addresses)")
    swap_parser.add_argument("--src", help="C file to install as the unit")
    args = parser.parse_args()
    paths = resolve_tools(args)
    extract(paths, args)
    init(paths, args.add_functions)
    if args.command == "swap":
        swap(args)
    write_names_header()
    write_build(paths)
    print(f"configured: dsd config in config/dsd, {len(swaps())} C unit(s); run `ninja`")


if __name__ == "__main__":
    main()
